<script setup>
import {ref} from 'vue';import {Database,RefreshCw} from 'lucide-vue-next';import {useArchive} from '../stores/archive';import {api,date} from '../services/api';import RetailMatchQueue from '../components/RetailMatchQueue.vue';import PipelinePanel from '../components/PipelinePanel.vue'
const tokenInput=ref('')
const store=useArchive(),jobs=ref([]),error=ref(''),busy=ref(false),result=ref('')
async function loadJobs(){error.value='';try{jobs.value=await api('/admin/collection-jobs',{token:store.adminToken})}catch(e){error.value=e.message}}
async function index(){busy.value=true;error.value='';try{const r=await api('/admin/reindex',{method:'POST',token:store.adminToken});result.value=`색인 완료: 메타데이터 ${r.metadata}건 / 문서 ${r.documents}청크`;await store.load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function connect(){
 busy.value=true;error.value='';result.value=''
 try{
  await store.connectAdmin(tokenInput.value);tokenInput.value='';result.value='관리자로 연결되었습니다.'
  try{await store.refreshCatalog();result.value+=' 최신 상품 확인을 요청했습니다.'}catch(e){error.value=e.message}
 }catch(e){error.value=e.message}finally{busy.value=false}
}
function disconnect(){store.disconnectAdmin();jobs.value=[];result.value='관리자 연결을 해제했습니다.';error.value=''}
</script>
<template><section class="page-heading"><p class="eyebrow">TRANSPARENCY FIRST</p><h1>데이터 현황</h1><p>얼마나 수집했고, 무엇이 아직 확인되지 않았는지.</p></section><div class="status-grid"><div class="status-card"><Database/><span>제품 데이터</span><strong>{{store.status?.figure_count??'—'}}</strong><small>공식 출처가 연결된 제품</small></div><div class="status-card"><span>메타데이터 컬렉션</span><strong>{{store.status?.index.metadata??0}}</strong><small>figure_metadata</small></div><div class="status-card"><span>외부 문서 컬렉션</span><strong>{{store.status?.index.documents??0}}</strong><small>figure_documents</small></div></div><section class="section"><div class="section-title"><h2>제조사별 수집 현황</h2><button @click="store.load" class="icon-button" aria-label="갱신"><RefreshCw :size="18"/></button></div><div class="table-wrap"><table><thead><tr><th>제조사</th><th>제품 수</th><th>확보 상태</th></tr></thead><tbody><tr v-for="m in store.makers" :key="m.id"><td>{{m.name_ko}} / {{m.name}}</td><td>{{m.count}}</td><td>{{m.count?'공식 메타데이터 일부 확보':'수집 대기'}}</td></tr></tbody></table></div></section><div class="notice"><p><strong>LLM:</strong> {{store.status?.llm_ready?'설정됨':'API 키 미설정'}} · <strong>웹 검색:</strong> {{store.status?.search_ready?'설정됨':'API 키 미설정'}}</p><p><strong>임베딩:</strong> {{store.status?.embedding_provider==='hash'?'Hash · 키 없는 어휘 검색 검증용 (의미 검색 모델 아님)':'API 임베딩'}}</p><p v-if="store.status?.index_error">{{store.status.index_error}}</p><p>이미지 재사용 권한, 신품·중고 수집 허가는 별도 확인 대상입니다. 수집 건수는 제조사의 전체 제품 수가 아닙니다.</p></div><section class="section"><h2>관리 도구</h2><form v-if="!store.isAdmin" class="admin-form" @submit.prevent="connect"><label>관리자 토큰<input type="password" v-model="tokenInput" autocomplete="off" required placeholder="서버의 ADMIN_TOKEN"></label><button class="button" :disabled="busy">{{busy?'연결 중…':'관리자로 연결'}}</button></form><div v-else class="admin-form"><span>관리자 연결됨</span><button class="button ghost" @click="loadJobs">수집 이력 조회</button><button class="button" @click="index" :disabled="busy">{{busy?'색인 중…':'전체 재색인'}}</button><button class="button ghost" @click="disconnect" :disabled="busy">관리자 연결 해제</button></div><p class="fine-print">관리자 연결은 현재 탭에서만 유지됩니다. 이 탭을 새로고침하면 인증을 확인하고 최신 상품을 갱신합니다.</p><p class="error" v-if="error">{{error}}</p><p class="notice" v-if="result">{{result}}</p><div class="table-wrap" v-if="store.isAdmin&&jobs.length"><table><thead><tr><th>작업</th><th>상태</th><th>건수</th><th>시작</th><th>오류</th></tr></thead><tbody><tr v-for="j in jobs" :key="j.id"><td>{{j.collector}}</td><td>{{j.status}}</td><td>{{j.count}}</td><td>{{date(j.started_at)}}</td><td>{{j.error_summary||'—'}}</td></tr></tbody></table></div></section><PipelinePanel v-if="store.isAdmin" class="section"/><RetailMatchQueue v-if="store.isAdmin" class="section"/></template>
